"""Generate the Linux wrapper that launches GCM under Proton."""

from __future__ import annotations

import os
import tempfile
from pathlib import Path

from .paths import Paths


def render_launcher_script(
    proton_root: str,
    steam_root: str,
    gcm_exe: str,
    prefix_dir: str,
) -> str:
    return f"""#!/usr/bin/env bash
# GCM Launcher wrapper - generated by the GCM Launcher Decky plugin.
set -e
unset LD_LIBRARY_PATH
unset LD_PRELOAD
unset STEAM_RUNTIME
unset STEAM_COMPAT_CLIENT_INSTALL_PATH
export STEAM_COMPAT_DATA_PATH="{prefix_dir}"
export STEAM_COMPAT_CLIENT_INSTALL_PATH="{steam_root}"
exec "{proton_root}/proton" run "{gcm_exe}"
"""


def write_launcher(paths: Paths, proton_root: str, steam_root: str) -> Path:
    paths.bin_dir.mkdir(parents=True, exist_ok=True)
    content = render_launcher_script(
        proton_root=proton_root,
        steam_root=steam_root,
        gcm_exe=str(paths.gcm_exe),
        prefix_dir=str(paths.prefix_dir),
    )
    fd, raw = tempfile.mkstemp(prefix=".gcm-launcher-", dir=paths.bin_dir)
    os.close(fd)
    temp_path = Path(raw)
    temp_path.write_text(content, encoding="utf-8")
    temp_path.chmod(0o755)
    temp_path.replace(paths.launcher_path)
    return paths.launcher_path
